import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Popover","description":"","frontmatter":{},"headers":[],"relativePath":"components/popover.md","filePath":"components/popover.md"}'),d={name:"components/popover.md"};function i(n,e,p,s,c,l){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="popover" tabindex="-1">Popover <a class="header-anchor" href="#popover" aria-label="Permalink to &quot;Popover&quot;">​</a></h1><p>Popover is a small surface that opens next to its trigger.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for a few settings, a small picker or an explanation that belong to one control. A list of actions is a menu (<a href="./dropdown">Dropdown</a> with <code>menu</code>); a form or a choice that stops the work is a <a href="./modal">Modal</a>; one word is a <a href="./tooltip">Tooltip</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>anchor</code></td><td>required</td><td>The trigger: a snippet of <code>(toggle, open)</code></td></tr><tr><td><code>align</code></td><td><code>start</code></td><td>The edge of the trigger it lines up with</td></tr><tr><td><code>up</code></td><td><code>false</code></td><td>Opens above the trigger, below only without room</td></tr><tr><td><code>gap</code></td><td><code>sm</code></td><td><code>0</code>, <code>sm</code>, <code>md</code> or <code>lg</code> between the children</td></tr><tr><td><code>openInitially</code></td><td><code>false</code></td><td>Open from the start</td></tr><tr><td><code>children</code></td><td>required</td><td>The content: a snippet of <code>(close)</code></td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The surface is a <a href="./bubble">Bubble</a>: the panel color, a strong line, the width of a popover and pad-md inside. It is placed as a <a href="./dropdown">Dropdown</a> is: in the top layer, below the trigger (above it when there is no room below; with <code>up</code>, above it, and below only when there is no room above), inside the window at the sides. A press outside, Escape or Tab closes it.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/popover/" title="Popover" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/popover/" target="_blank" rel="noopener">Popover</a></figcaption></figure>',10)])])}const f=o(d,[["render",i]]);export{m as __pageData,f as default};
